#!/usr/bin/env bash
# Assemble BENCHMARKS.md, the snapshot every release attaches (design v3 §1.2).
#
# It is assembled from what is committed under docs/benchmarks/results/, not
# regenerated by running benchmarks here. That is deliberate. A release is built
# on a GitHub runner, and numbers measured on a shared cloud VM are not a
# snapshot of "the reference configuration" — publishing them as one would make
# the file actively misleading. What this does instead is collect the measured
# results, each of which discloses the hardware it came from, so a reader can
# see what was measured and on what.
#
#   scripts/make-benchmarks.sh > BENCHMARKS.md
set -euo pipefail

cd "$(dirname "$0")/.."
results="docs/benchmarks/results"

emit_summary() {
  local f="$1"
  # The first heading and the first paragraph after it: enough to say what the
  # file measured without duplicating it.
  awk '
    /^# / && !seen { sub(/^# /, ""); print "### " $0; seen = 1; next }
    seen && NF && !/^#/ && !body { body = 1 }
    body && NF { print; next }
    body && !NF { exit }
  ' "$f"
}

cat <<'HEADER'
# Benchmarks

A snapshot of what has actually been measured, assembled from the result files
under [`docs/benchmarks/results/`](docs/benchmarks/results/). Every release
attaches this file.

It is assembled from committed results rather than regenerated at release time:
a release is built on a shared cloud runner, and numbers from one are not a
snapshot of any reference configuration. Each result below discloses the machine
it came from.

**Read the caveats in each result file before quoting a number from it.** The
task-success results in particular settle nothing: every arm's confidence
interval overlaps every other's.

HEADER

printf '## What has been measured\n\n'
printf '| Result | Measured |\n|---|---|\n'
for f in "$results"/*.md; do
  base="$(basename "$f")"
  [ "$base" = "README.md" ] && continue
  title="$(awk '/^# /{sub(/^# /, ""); print; exit}' "$f")"
  printf '| [`%s`](%s/%s) | %s |\n' "$base" "$results" "$base" "$title"
done

printf '\n'
for f in "$results"/*.md; do
  base="$(basename "$f")"
  [ "$base" = "README.md" ] && continue
  printf '## %s\n\n' "$base"
  emit_summary "$f"
  printf '\nFull result: [`%s/%s`](%s/%s)\n\n' "$results" "$base" "$results" "$base"
done

printf -- '---\n\n'
printf 'Regenerate with `make benchmarks`. CI fails if this file is out of date\n'
printf 'with the results it summarises, so a published snapshot cannot drift away\n'
printf 'from the measurements it claims to describe.\n'
